module good_sequence_solver (input clk, input rst_n, input start, input [3:0] n, input [15:0] a [0:15], output reg [7:0] result, output reg done); parameter MAX_PRIME = 256; reg [7:0] dp[MAX_PRIME]; localparam IDLE = 4'd0, READ = 4'd1, CALC = 4'd2, UPDATE = 4'd3, DONE = 4'd4; reg [3:0] state; reg [3:0] element_index; reg [15:0] current_num; reg [7:0] max_len; reg [3:0] n_val; function automatic reg [7:0] get_max_dp(input reg [15:0] x); reg [7:0] max_val; max_val = 0; if (x !=0 && (x & 1) ==0) begin if (dp[2] > max_val) max_val = dp[2]; end if (x !=0 && x % 3 ==0) begin if (dp[3] > max_val) max_val = dp[3]; end if (x !=0 && x %5 ==0) begin if (dp[5] > max_val) max_val = dp[5]; end return max_val; endfunction function automatic reg [7:0] update_dp_and_get_new_length(input reg [15:0] x, input reg [7:0] current_max); reg [7:0] new_len; new_len = current_max +1; if (x !=0 && (x &1)==0) dp[2] = new_len; if (x !=0 && x%3 ==0) dp[3] = new_len; if (x !=0 && x%5 ==0) dp[5] = new_len; return new_len; endfunction initial begin state <= IDLE; element_index <= 0; max_len <= 0; done <= 0; dp <= 0; n_val <= n; end always @(posedge clk) begin if (!rst_n) begin state <= IDLE; element_index <= 0; max_len <= 0; done <= 0; dp <= 0; n_val <= n; end else begin reg [7:0] current_max, new_len; case(state) IDLE: begin if (start) begin state <= READ; element_index <= 0; current_num <= a[element_index]; end end READ: begin state <= CALC; end CALC: begin current_max = get_max_dp(current_num); state <= UPDATE; end UPDATE: begin new_len = update_dp_and_get_new_length(current_num, current_max); if (new_len > max_len) max_len = new_len; element_index <= element_index +1; if (element_index < n_val) begin state <= READ; current_num <= a[element_index]; end else begin state <= DONE; result <= max_len; done <= 1; end end DONE: ; default: state <= IDLE; endcase end end endmodule